package fr.hydrosea.comptage.application;import static fr.hydrosea.comptage.application.ModelesComptage.*;import fr.hydrosea.evenements.application.PortEvenements;import java.util.List;import java.util.Map;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ServiceComptage{private final PortComptage port;private final PortEvenements evenements;public ServiceComptage(PortComptage port,PortEvenements evenements){this.port=port;this.evenements=evenements;}public List<VueCompteur> lister(){return port.listerCompteurs();}public VueCompteur consulter(UUID id){return port.obtenirCompteur(id);}@Transactional public VueCompteur creer(CommandeCreerCompteur c,UUID correlation){UUID id=UUID.randomUUID();var v=port.creer(id,c);publier("COMPTEUR_ENREGISTRE","COMPTEUR",id,correlation);return v;}@Transactional public VueCompteur modifier(UUID id,int version,CommandeModifierCompteur c,UUID correlation){var v=port.modifier(id,version,c);publier("COMPTEUR_MODIFIE","COMPTEUR",id,correlation);return v;}@Transactional public VueAffectation poser(UUID id,int version,CommandePoserCompteur c,UUID correlation){var v=port.poser(id,version,c);publier("COMPTEUR_POSE","COMPTEUR",id,correlation);publier("AFFECTATION_CREEE","AFFECTATION_COMPTEUR",v.id(),correlation);return v;}public List<VueAffectation> listerAffectations(){return port.listerAffectations();}public VueAffectation consulterAffectation(UUID id){return port.obtenirAffectation(id);}private void publier(String type,String agregat,UUID id,UUID correlation){evenements.enregistrer(type,agregat,id,correlation,Map.of("identifiant",id));}}
